import logging
from typing import Any, Tuple, Union

import requests
from requests.exceptions import ConnectTimeout

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.devices.base import PDU
from taf.hw.pdu.exceptions import BadPortNumber, BadResponse, Timeout


class RRBRequests(object):
    PROTOCOL = "http"
    STATUSES_ENDPOINTS = ["outletStatuses.php", "getPortState.php"]
    ACTION_ENDPOINT = "execmd.php"
    DEFAULT_TIMEOUT = 30
    DEFAULT_USERNAME = "admin"

    def __init__(self, host: str, timeout: Union[float, Tuple], **kwargs: Any):
        self._host = host
        self._timeout = timeout
        self._http_proxy = (
            {"http": kwargs.get("http_proxy")} if kwargs.get("http_proxy") else None
        )

    def get_all_port_statuses(self):
        response = ""
        exc_msg = []
        end_point = ""
        try:
            for file in self.STATUSES_ENDPOINTS:
                statuses_url = self._create_url(file)
                response = requests.get(
                    url=statuses_url, timeout=self._timeout, proxies=self._http_proxy
                )
                if response.status_code == 200:
                    end_point = file
                    break
        except ConnectTimeout as exc:
            exc_msg.append(f"Connection to RRB timed out: {str(exc)}")
            raise Timeout(exc_msg)
        statuses = response.json()
        statuses = self._standarize_ports_from_server_to_client(statuses, end_point)

        return statuses

    def set_port_status(self, port, status, used_by=DEFAULT_USERNAME):
        port = self._standarize_port_from_client_to_server(port)
        data = [("port", port), ("index", port), ("state", status), ("usedby", used_by)]

        set_url = self._create_url(self.ACTION_ENDPOINT)
        response = requests.post(
            url=set_url, data=data, timeout=self._timeout, proxies=self._http_proxy
        )

        self._verify_response(response)

    def _create_url(self, endpoint):
        url = f"{self.PROTOCOL}://{self._host}/RRB/{endpoint}"
        return url

    def _verify_response(self, response):
        if len(response.content) > 0:
            exc_msg = "Expected response to be empty, actual response: {}"
            exc_msg = exc_msg.format(response.content)
            raise BadResponse(exc_msg)

    def _standarize_port_from_client_to_server(self, port):
        # RRB web interface start counting from 1,
        # but requests need to start counting from 0.
        port -= 1
        port = str(port)
        return port

    def _standarize_ports_from_server_to_client(self, statuses, end_point):
        # RRB web interface gives port numbers that start
        # counting from 0, but client need to start counting from 1.
        if end_point == "outletStatuses.php":
            statuses = {int(k) + 1: v for k, v in statuses.items()}
        else:
            statuses = {int(item["port"]) + 1: item["status"] for item in statuses}
        return statuses


class RRB(PDU):
    def __init__(self, host, timeout=RRBRequests.DEFAULT_TIMEOUT, **kwargs):
        super(RRB, self).__init__(host=host)
        self._request = RRBRequests(host, timeout, **kwargs)

    def get_port_status(self, port):
        msg = f"RRB: Fetching status of port: {port}"
        logging.info(msg)

        statuses = self._request.get_all_port_statuses()
        self._verify_port_number_correct(port, statuses)

        port_status_code = statuses[port]
        port_status = self._reversed_port_settings[port_status_code]
        return port_status

    def _set_port_status(self, port, status):
        msg = f"RRB: Setting port to {status}: {port}"
        logging.info(msg)

        self._request.set_port_status(port, self._port_setting[status])

    def _verify_port_number_correct(self, port, statuses):
        if port not in statuses:
            exc_msg = f"Port number is invalid: {port}"
            raise BadPortNumber(exc_msg)

    @property
    def _port_setting(self):
        return {DeviceStatus.OFF: "0", DeviceStatus.ON: "1"}
